insert into public.panda_records(kind,id,data) values('recipes','recipe_01','{"id":"recipe_01","name":"Blueberry protein overnight oats","name_ar":"شوفان ليلي بالتوت الأزرق","category":"Breakfast","minutes":5,"wait_minutes":240,"servings":1,"summary":"A simple start, with clear portions and everyday ingredients.","summary_ar":"بداية بسيطة بمقادير واضحة ومكونات يومية.","ingredients":[{"id":"oats","name":"Rolled oats · dry","name_ar":"شوفان ملفوف · جاف","protein":13,"carbs":60,"fat":7,"fiber":10,"allergens":"Gluten","unit":"g","quantity":50},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":170},{"id":"milk","name":"Milk · 1.5% fat","name_ar":"حليب قليل الدسم","protein":3.5,"carbs":5,"fat":1.5,"fiber":0,"allergens":"Milk","unit":"g","quantity":80},{"id":"blueberry","name":"Blueberries · fresh","name_ar":"توت أزرق طازج","protein":0.7,"carbs":12,"fat":0.3,"fiber":2.4,"allergens":"","unit":"g","quantity":80},{"id":"chia","name":"Chia seeds","name_ar":"بذور الشيا","protein":17,"carbs":8,"fat":31,"fiber":34,"allergens":"","unit":"g","quantity":10}],"steps":["Stir the oats, yogurt, milk and chia in a jar until evenly combined.","Cover and refrigerate for at least 4 hours, or overnight.","Stir again and top with the washed blueberries before serving."],"steps_ar":["اخلط الشوفان والزبادي والحليب والشيا في وعاء.","غطه وضعه في الثلاجة ٤ ساعات على الأقل أو طوال الليل.","قلبه مرة أخرى وأضف التوت المغسول قبل التقديم."],"tags":["No-cook","Vegetarian"],"allergens":["Gluten","Milk"],"image":"assets/recipes/01.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"