insert into public.panda_records(kind,id,data) values('recipes','recipe_03','{"id":"recipe_03","name":"Spinach feta omelette","name_ar":"أومليت السبانخ والفيتا","category":"Breakfast","minutes":15,"wait_minutes":0,"servings":1,"summary":"A simple start, with clear portions and everyday ingredients.","summary_ar":"بداية بسيطة بمقادير واضحة ومكونات يومية.","ingredients":[{"id":"egg","name":"Whole egg · shell removed","name_ar":"بيض كامل دون القشرة","protein":12.6,"carbs":0.7,"fat":9.5,"fiber":0,"allergens":"Egg","unit":"g","quantity":100},{"id":"spinach","name":"Spinach · raw","name_ar":"سبانخ نيئة","protein":2.9,"carbs":1.4,"fat":0.4,"fiber":2.2,"allergens":"","unit":"g","quantity":60},{"id":"feta","name":"Feta cheese","name_ar":"جبنة فيتا","protein":14,"carbs":4,"fat":21,"fiber":0,"allergens":"Milk","unit":"g","quantity":30},{"id":"tomato","name":"Tomatoes · raw","name_ar":"طماطم نيئة","protein":0.9,"carbs":2.7,"fat":0.2,"fiber":1.2,"allergens":"","unit":"g","quantity":100},{"id":"bread","name":"Wholegrain bread","name_ar":"خبز حبوب كاملة","protein":10,"carbs":40,"fat":4,"fiber":7,"allergens":"Wheat, Gluten","unit":"g","quantity":50},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":4}],"steps":["Wilt the spinach in the oil in a small non-stick pan. Beat the eggs and pour over the spinach.","Cook gently, add the feta and fold when the egg is fully set.","Toast the bread and serve with the omelette and tomatoes."],"steps_ar":["ذبّل السبانخ بالزيت في مقلاة صغيرة ثم أضف البيض المخفوق.","اطه بهدوء وأضف الفيتا واطو الأومليت بعد نضج البيض تماماً.","حمص الخبز وقدمه مع الأومليت والطماطم."],"tags":["Vegetarian"],"allergens":["Egg","Gluten","Milk","Wheat"],"image":"assets/recipes/03.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_04','{"id":"recipe_04","name":"Greek yogurt berry crunch","name_ar":"زبادي يوناني بالتوت واللوز","category":"Breakfast","minutes":5,"wait_minutes":0,"servings":1,"summary":"A simple start, with clear portions and everyday ingredients.","summary_ar":"بداية بسيطة بمقادير واضحة ومكونات يومية.","ingredients":[{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":250},{"id":"blueberry","name":"Blueberries · fresh","name_ar":"توت أزرق طازج","protein":0.7,"carbs":12,"fat":0.3,"fiber":2.4,"allergens":"","unit":"g","quantity":60},{"id":"strawberry","name":"Strawberries · fresh","name_ar":"فراولة طازجة","protein":0.7,"carbs":5.7,"fat":0.3,"fiber":2,"allergens":"","unit":"g","quantity":80},{"id":"oats","name":"Rolled oats · dry","name_ar":"شوفان ملفوف · جاف","protein":13,"carbs":60,"fat":7,"fiber":10,"allergens":"Gluten","unit":"g","quantity":30},{"id":"almond","name":"Almonds","name_ar":"لوز","protein":21,"carbs":9,"fat":50,"fiber":12.5,"allergens":"Tree nuts","unit":"g","quantity":15}],"steps":["Wash the berries and slice the strawberries.","Spoon the yogurt into a bowl and add the oats.","Top with the berries and chopped almonds. Serve immediately to keep the crunch."],"steps_ar":["اغسل التوت وقطع الفراولة.","ضع الزبادي في وعاء وأضف الشوفان.","أضف الفاكهة واللوز المفروم وقدم فوراً للحفاظ على القرمشة."],"tags":["No-cook","Vegetarian"],"allergens":["Gluten","Milk","Tree nuts"],"image":"assets/recipes/04.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
