insert into public.panda_records(kind,id,data) values('recipes','recipe_06','{"id":"recipe_06","name":"Cottage cheese pineapple bowl","name_ar":"جبنة قريش بالأناناس والجوز","category":"Breakfast","minutes":5,"wait_minutes":0,"servings":1,"summary":"A simple start, with clear portions and everyday ingredients.","summary_ar":"بداية بسيطة بمقادير واضحة ومكونات يومية.","ingredients":[{"id":"cottage","name":"Cottage cheese · 2% fat","name_ar":"جبنة قريش قليلة الدسم","protein":12,"carbs":3,"fat":2,"fiber":0,"allergens":"Milk","unit":"g","quantity":220},{"id":"pineapple","name":"Pineapple · peeled","name_ar":"أناناس مقشر","protein":0.5,"carbs":12,"fat":0.1,"fiber":1.4,"allergens":"","unit":"g","quantity":150},{"id":"oats","name":"Rolled oats · dry","name_ar":"شوفان ملفوف · جاف","protein":13,"carbs":60,"fat":7,"fiber":10,"allergens":"Gluten","unit":"g","quantity":30},{"id":"walnut","name":"Walnuts","name_ar":"جوز","protein":15,"carbs":7,"fat":65,"fiber":6.7,"allergens":"Tree nuts","unit":"g","quantity":15}],"steps":["Cut the peeled pineapple into bite-size chunks.","Spoon the cottage cheese into a bowl and scatter over the oats.","Add the pineapple and chopped walnuts."],"steps_ar":["قطع الأناناس المقشر إلى مكعبات صغيرة.","ضع جبنة القريش في وعاء ورش الشوفان.","أضف الأناناس والجوز المفروم."],"tags":["No-cook","Vegetarian"],"allergens":["Gluten","Milk","Tree nuts"],"image":"assets/recipes/06.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
