sion":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_11','{"id":"recipe_11","name":"Turkey and kidney bean chili","name_ar":"تشيلي الديك الرومي والفاصوليا","category":"Main meals","minutes":35,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"turkey","name":"Turkey mince · raw, lean","name_ar":"ديك رومي مفروم نيئ قليل الدهن","protein":22,"carbs":0,"fat":5,"fiber":0,"allergens":"","unit":"g","quantity":160},{"id":"kidney","name":"Kidney beans · canned, drained","name_ar":"فاصوليا حمراء معلبة ومصفاة","protein":7.5,"carbs":14,"fat":0.5,"fiber":6,"allergens":"","unit":"g","quantity":100},{"id":"passata","name":"Passata · plain tomato","name_ar":"طماطم مهروسة سادة","protein":1.5,"carbs":4,"fat":0.3,"fiber":1.5,"allergens":"","unit":"g","quantity":180},{"id":"pepper","name":"Bell pepper · raw","name_ar":"فلفل حلو نيئ","protein":1,"carbs":4,"fat":0.3,"fiber":2.1,"allergens":"","unit":"g","quantity":100},{"id":"onion","name":"Onion · raw","name_ar":"بصل نيئ","protein":1.1,"carbs":7.5,"fat":0.1,"fiber":1.7,"allergens":"","unit":"g","quantity":50},{"id":"brownrice","name":"Brown rice · dry","name_ar":"أرز بني جاف","protein":7.5,"carbs":73,"fat":2.7,"fiber":3.5,"allergens":"","unit":"g","quantity":50},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":5},{"id":"spice","name":"Ground spice mix · unsalted","name_ar":"بهارات مطحونة دون ملح","protein":10,"carbs":35,"fat":10,"fiber":20,"allergens":"Check blend","unit":"g","quantity":3}],"steps":["Start cooking the brown rice. Soften onion and pepper in oil, then add the turkey and break it up.","Add passata, drained kidney beans and spices. Simmer 15–20 minutes, adding water if needed; turkey must reach 74°C.","Serve the chili over the rice. Divide cooked batches evenly if making extra portions."],"steps_ar":["ابدأ بطهي الأرز ولين البصل والفلفل بالزيت ثم أضف الديك الرومي وفتته.","أضف الطماطم والفاصوليا المصفاة والبهارات واطه ١٥–٢٠ دقيقة حتى تبلغ حرارة اللحم ٧٤°م.","قدم التشيلي فوق الأرز وقسم الكمية بالتساوي إذا حضرت حصصاً إضافية."],"tags":["Meal prep"],"allergens":["Check blend"],"image":"assets/recipes/11.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_12','{"id":"recipe_12","name":"Lean beef burrito bowl","name_ar":"بول البوريتو باللحم البقري","category":"Main meals","minutes":25,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"beef","name":"Beef mince · raw, 5% fat","name_ar":"لحم بقري مفروم نيئ ٥٪ دهون","protein":21,"carbs":0,"fat":5,"fiber":0,"allergens":"","unit":"g","quantity":150},{"id":"rice","name":"Basmati rice · dry","name_ar":"أرز بسمتي جاف","protein":7.5,"carbs":78,"fat":0.7,"fiber":1.2,"allergens":"","unit":"g","quantity":50},{"id":"blackbean","name":"Black beans · cooked, drained","name_ar":"فاصوليا سوداء مطبوخة ومصفاة","protein":8.9,"carbs":15,"fat":0.5,"fiber":8.7,"allergens":"","unit":"g","quantity":80},{"id":"corn","name":"Sweetcorn · canned, drained","name_ar":"ذرة حلوة معلبة ومصفاة","protein":3,"carbs":16,"fat":1.5,"fiber":2.5,"allergens":"","unit":"g","quantity":60},{"id":"tomato","name":"Tomatoes · raw","name_ar":"طماطم نيئة","protein":0.9,"carbs":2.7,"fat":0.2,"fiber":1.2,"allergens":"","unit":"g","quantity":100},{"id":"avocado","name":"Avocado · flesh only","name_ar":"لب الأفوكادو","protein":2,"carbs":1.8,"fat":15,"fiber":6.7,"allergens":"","unit":"g","quantity":40},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":4},{"id":"spice","name":"Ground spice mix · unsalted","name_ar":"بهارات مطحونة دون ملح","protein":10,"carbs":35,"fat":10,"fiber":20,"allergens":"Check blend","unit":"g","quantity":3}],"steps":["Cook the rice. Brown the mince in oil with the spices, breaking it into small pieces; cook to 71°C.","Warm the drained beans and corn. Dice the tomatoes and slice the avocado.","Arrange rice, beef and vegetables in a bowl. Serve all measured components together."],"steps_ar":["اطه الأرز وحمر اللحم المفروم بالز