insert into public.panda_records(kind,id,data) values('recipes','recipe_13','{"id":"recipe_13","name":"Salmon, sweet potato and asparagus","name_ar":"سلمون بالبطاطا الحلوة والهليون","category":"Main meals","minutes":35,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"salmon","name":"Salmon fillet · raw","name_ar":"فيليه سلمون نيئ","protein":20,"carbs":0,"fat":13,"fiber":0,"allergens":"Fish","unit":"g","quantity":150},{"id":"sweetpotato","name":"Sweet potato · raw","name_ar":"بطاطا حلوة نيئة","protein":1.6,"carbs":17,"fat":0.1,"fiber":3,"allergens":"","unit":"g","quantity":220},{"id":"asparagus","name":"Asparagus · raw","name_ar":"هليون نيئ","protein":2.2,"carbs":1.8,"fat":0.1,"fiber":2.1,"allergens":"","unit":"g","quantity":150},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":5},{"id":"lemon","name":"Lemon juice","name_ar":"عصير ليمون","protein":0.4,"carbs":2.5,"fat":0.2,"fiber":0.3,"allergens":"","unit":"g","quantity":20}],"steps":["Heat the oven to 200°C. Cube the sweet potato, toss with oil and roast for 15 minutes.","Add the salmon and asparagus to the tray. Roast about 12–15 minutes more, until salmon reaches 63°C.","Check the potato is tender and finish with lemon juice."],"steps_ar":["سخن الفرن إلى ٢٠٠°م وقطع البطاطا واخلطها بالزيت واشوها ١٥ دقيقة.","أضف السلمون والهليون واشو ١٢–١٥ دقيقة إضافية حتى يبلغ السلمون ٦٣°م.","تأكد من طراوة البطاطا وأضف عصير الليمون."],"tags":["Tray bake"],"allergens":["Fish"],"image":"assets/recipes/13.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
