insert into public.panda_records(kind,id,data) values('recipes','recipe_32','{"id":"recipe_32","name":"Hummus, vegetables and pita","name_ar":"حمص بالطحينة مع الخضار والبيتا","category":"Snacks","minutes":10,"wait_minutes":0,"servings":1,"summary":"An easy extra to fit around your assigned meals.","summary_ar":"خيار سهل يناسب جدول وجباتك المحدد.","ingredients":[{"id":"hummus","name":"Hummus · prepared","name_ar":"حمص بالطحينة جاهز","protein":7,"carbs":10,"fat":10,"fiber":5,"allergens":"Sesame","unit":"g","quantity":100},{"id":"carrot","name":"Carrot · raw","name_ar":"جزر نيئ","protein":0.9,"carbs":6.8,"fat":0.2,"fiber":2.8,"allergens":"","unit":"g","quantity":100},{"id":"cucumber","name":"Cucumber · raw","name_ar":"خيار نيئ","protein":0.7,"carbs":2,"fat":0.1,"fiber":0.5,"allergens":"","unit":"g","quantity":100},{"id":"pepper","name":"Bell pepper · raw","name_ar":"فلفل حلو نيئ","protein":1,"carbs":4,"fat":0.3,"fiber":2.1,"allergens":"","unit":"g","quantity":80},{"id":"pita","name":"Wholegrain pita","name_ar":"خبز بيتا كامل الحبوب","protein":9,"carbs":48,"fat":2,"fiber":6,"allergens":"Wheat, Gluten","unit":"g","quantity":50}],"steps":["Wash the vegetables and cut into thick dipping sticks.","Warm the pita and cut into triangles.","Spoon hummus into a small bowl and arrange vegetables and pita alongside."],"steps_ar":["اغسل الخضار وقطعها إلى أصابع سميكة.","سخن خبز البيتا وقطعه مثلثات.","ضع الحمص في وعاء ورتب الخضار والخبز بجانبه."],"tags":["Vegan","Quick"],"allergens":["Gluten","Sesame","Wheat"],"image":"assets/recipes/32.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::