insert into public.panda_records(kind,id,data) values('recipes','recipe_33','{"id":"recipe_33","name":"Apple peanut yogurt bowl","name_ar":"بول الزبادي والتفاح والفول السوداني","category":"Snacks","minutes":5,"wait_minutes":0,"servings":1,"summary":"An easy extra to fit around your assigned meals.","summary_ar":"خيار سهل يناسب جدول وجباتك المحدد.","ingredients":[{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":200},{"id":"apple","name":"Apple · core removed","name_ar":"تفاح دون البذور","protein":0.3,"carbs":11.5,"fat":0.2,"fiber":2.4,"allergens":"","unit":"g","quantity":150},{"id":"peanut","name":"Peanut butter · unsweetened","name_ar":"زبدة فول سوداني دون سكر","protein":25,"carbs":12,"fat":50,"fiber":6,"allergens":"Peanuts","unit":"g","quantity":15},{"id":"cinnamon","name":"Cinnamon · ground","name_ar":"قرفة مطحونة","protein":4,"carbs":28,"fat":1,"fiber":53,"allergens":"","unit":"g","quantity":1}],"steps":["Core and slice the apple. Spoon yogurt into a bowl.","Thin peanut butter with a little warm water if needed, then drizzle over the yogurt.","Add apple slices and cinnamon."],"steps_ar":["أزل بذور التفاح وقطعه وضع الزبادي في وعاء.","خفف زبدة الفول السوداني بقليل من الماء الدافئ عند الحاجة ووزعها على الزبادي.","أضف شرائح التفاح والقرفة."],"tags":["Vegetarian","No-cook"],"allergens":["Milk","Peanuts"],"image":"assets/recipes/33.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_34','{"id":"recipe_34","name":"Tuna cucumber rice cakes","name_ar":"كعك الأرز بالتونة والخيار","category":"Snacks","minutes":10,"wait_minutes":0,"servings":1,"summary":"An easy extra to fit around your assigned meals.","summary_ar":"خيار سهل يناسب جدول وجباتك المحدد.","ingredients":[{"id":"tuna","name":"Tuna in water · drained","name_ar":"تونة بالماء مصفاة","protein":25,"carbs":0,"fat":1,"fiber":0,"allergens":"Fish","unit":"g","quantity":120},{"id":"ricecake","name":"Plain rice cakes","name_ar":"كعك أرز سادة","protein":8,"carbs":80,"fat":3,"fiber":3,"allergens":"","unit":"g","quantity":30},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":40},{"id":"cucumber","name":"Cucumber · raw","name_ar":"خيار نيئ","protein":0.7,"carbs":2,"fat":0.1,"fiber":0.5,"allergens":"","unit":"g","quantity":80},{"id":"lemon","name":"Lemon juice","name_ar":"عصير ليمون","protein":0.4,"carbs":2.5,"fat":0.2,"fiber":0.3,"allergens":"","unit":"g","quantity":10}],"steps":["Drain tuna thoroughly, then mix with yogurt and lemon juice.","Slice cucumber thinly and arrange on the rice cakes.","Top with tuna and eat soon after assembling to keep the rice cakes crisp."],"steps_ar":["صف التونة جيداً واخلطها بالزبادي وعصير الليمون.","قطع الخيار رفيعاً ورتبه على كعك الأرز.","أضف التونة وتناولها بعد التحضير للحفاظ على القرمشة."],"tags":["No-cook"],"allergens":["Fish","Milk"],"image":"assets/recipes/34.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_35','{"id":"recipe_35","name":"Egg and potato salad","name_ar":"سلطة البيض والبطاطس","category":"Main meals","minutes":30,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"egg","name":"Whole egg · shell removed","name_ar":"بيض كامل دون القشرة","protein":12.6,"carbs":0.7,"fat":9.5,"fiber":0,"allergens":"Egg","unit":"g","quantity":100},{"id":"potato","name":"Potato · raw","name_ar":"بطاطس نيئة","protein":2,"carbs":16,"fat":0.1,"fiber":2.2,"allergens":"","unit":"g","quantity":250},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":100},{"id":"cucumber","name":"Cucumber · raw","name_ar":"خيار نيئ","protein":0.7,"carbs":2,"fat":0.1,"fiber":0.5,"allergens":"","unit":"g","quantity":100},{"id":"parsley","name":"Parsley · fresh","name_ar":"بقدونس طازج","protein":3,"carbs":3,"fat":0.8,"fiber":3.3,"allergens":"","unit":"g","quantity":10},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":5},{"id":"lemon","name":"Lemon juice","name_ar":"عصير ليمون","protein":0.4,"carbs":2.5,"fat":0.2,"fiber":0.3,"allergens":"","unit":"g","quantity":15}],"steps":["Boil the eggs until firm. Cut potatoes into even pieces and simmer separately until tender, then drain.","Cool briefly, peel eggs and chop. Mix yogurt, lemon, oil and parsley.","Fold potatoes, eggs and cucumber into the dressing. Serve or chill promptly."],"steps_ar":["اسلق البيض حتى يتماسك وقطع البطاطس واطهها في قدر منفصل حتى تلين ثم صفها.","بردها قليلاً وقشر البيض وقطعه واخلط الزبادي والليمون والزيت والبقدونس.","قلب البطاطس والبيض والخيار مع الصلصة وقدمها أو بردها سريعاً."],"tags":["Vegetarian","Meal prep"],"allergens":["Egg","Milk"],"image":"assets/recipes/35.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_36','{"id":"recipe_36","name":"Chicken vegetable soup","name_ar":"شوربة الدجاج والخضار","category":"Main meals","minutes":35,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"chicken","name":"Chicken breast · raw, skinless","name_ar":"صدر دجاج نيئ دون الجلد","protein":23,"carbs":0,"fat":2,"fiber":0,"allergens":"","unit":"g","quantity":170},{"id":"potato","name":"Potato · raw","name_ar":"بطاطس نيئة","protein":2,"carbs":16,"fat":0.1,"fiber":2.2,"allergens":"","unit":"g","quantity":150},{"id":"carrot","name":"Carrot · raw","name_ar":"جزر نيئ","protein":0.9,"carbs":6.8,"fat":0.2,"fiber":2.8,"allergens":"","unit":"g","quantity":100},{"id":"celery","name":"Celery · raw","name_ar":"كرفس نيئ","protein":0.7,"carbs":1.5,"fat":0.2,"fiber":1.6,"allergens":"Celery","unit":"g","quantity":60},{"id":"onion","name":"Onion · raw","name_ar":"بصل نيئ","protein":1.1,"carbs":7.5,"fat":0.1,"fiber":1.7,"allergens":"","unit":"g","quantity":50},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":5},{"id":"water","name":"Water","name_ar":"ماء","protein":0,"carbs":0,"fat":0,"fiber":0,"allergens":"","unit":"g","quantity":350},{"id":"parsley","name":"Parsley · fresh","name_ar":"بقدونس طازج","protein":3,"carbs":3,"fat":0.8,"fiber":3.3,"allergens":"","unit":"g","quantity":10}],"steps":["Soften diced onion, carrot and celery in oil for 5 minutes.","Add cubed chicken, potato and water. Bring to a simmer and cook 20 minutes or until potato is tender and chicken reaches 74°C.","Stir in chopped parsley and serve hot. Adjust thickness with water as needed."],"steps_ar":["لين البصل والجزر والكرفس المقطع بالزيت ٥ دقائق.","أضف مكعبات الدجاج والبطاطس والماء واطه ٢٠ دقيقة حتى تلين البطاطس ويبلغ الدجاج ٧٤°م.","أضف البقدونس وقدم ساخناً واضبط القوام بالماء عند الحاجة."],"tags":["Meal prep"],"allergens":["Celery"],"image":"assets/recipes/36.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_37','{"id":"recipe_37","name":"Salmon quinoa salad","name_ar":"سلطة السلمون والكينوا","category":"Main meals","minutes":25,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"salmon","name":"Salmon fillet · raw","name_ar":"فيليه سلمون نيئ","protein":20,"carbs":0,"fat":13,"fiber":0,"allergens":"Fish","unit":"g","quantity":140},{"id":"quinoa","name":"Quinoa · cooked","name_ar":"كينوا مطبوخة","protein":4.4,"carbs":18.7,"fat":1.9,"fiber":2.8,"allergens":"","unit":"g","quantity":150},{"id":"spinach","name":"Spinach · raw","name_ar":"سبانخ نيئة","protein":2.9,"carbs":1.4,"fat":0.4,"fiber":2.2,"allergens":"","unit":"g","quantity":50},{"id":"cucumber","name":"Cucumber · raw","name_ar":"خيار نيئ","protein":0.7,"carbs":2,"fat":0.1,"fiber":0.5,"allergens":"","unit":"g","quantity":100},{"id":"tomato","name":"Tomatoes · raw","name_ar":"طماطم نيئة","protein":0.9,"carbs":2.7,"fat":0.2,"fiber":1.2,"allergens":"","unit":"g","quantity":100},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":5},{"id":"lemon","name":"Lemon juice","name_ar":"عصير ليمون","protein":0.4,"carbs":2.5,"fat":0.2,"fiber":0.3,"allergens":"","unit":"g","quantity":20}],"steps":["Bake salmon at 200°C until its centre reaches 63°C, about 12–15 minutes depending on thickness.","Weigh cooked quinoa and combine with spinach, chopped cucumber and tomatoes.","Flake the salmon over the salad and dress with measured oil and lemon."],"steps_ar":["اخبز السلمون على ٢٠٠°م حتى تبلغ حرارته الداخلية ٦٣°م نحو ١٢–١٥ دقيقة حسب السمك.","زن الكينوا المطبوخة واخلطها بالسبانخ والخيار والطماطم.","فتت السلمون فوق السلطة وأضف الزيت المحدد والليمون."],"tags":["Meal prep"],"allergens":["Fish"],"image":"assets/recipes/37.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_38','{"id":"recipe_38","name":"Turkey burger and potato wedges","name_ar":"برغر الديك الرومي وشرائح البطاطس","category":"Main meals","minutes":40,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"turkey","name":"Turkey mince · raw, lean","name_ar":"ديك رومي مفروم نيئ قليل الدهن","protein":22,"carbs":0,"fat":5,"fiber":0,"allergens":"","unit":"g","quantity":170},{"id":"bread","name":"Wholegrain bread","name_ar":"خبز حبوب كاملة","protein":10,"carbs":40,"fat":4,"fiber":7,"allergens":"Wheat, Gluten","unit":"g","quantity":70},{"id":"potato","name":"Potato · raw","name_ar":"بطاطس نيئة","protein":2,"carbs":16,"fat":0.1,"fiber":2.2,"allergens":"","unit":"g","quantity":180},{"id":"tomato","name":"Tomatoes · raw","name_ar":"طماطم نيئة","protein":0.9,"carbs":2.7,"fat":0.2,"fiber":1.2,"allergens":"","unit":"g","quantity":80},{"id":"spinach","name":"Spinach · raw","name_ar":"سبانخ نيئة","protein":2.9,"carbs":1.4,"fat":0.4,"fiber":2.2,"allergens":"","unit":"g","quantity":20},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":40},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":7},{"id":"spice","name":"Ground spice mix · unsalted","name_ar":"بهارات مطحونة دون ملح","protein":10,"carbs":35,"fat":10,"fiber":20,"allergens":"Check blend","unit":"g","quantity":3}],"steps":["Heat the oven to 200°C. Toss potato wedges in half the oil and roast 30–35 minutes, turning once.","Shape turkey and spices into a patty. Pan-cook with remaining oil until its centre reaches 74°C.","Serve between two wholegrain bread slices with yogurt, tomato and spinach, with wedges alongside."],"steps_ar":["سخن الفرن إلى ٢٠٠°م واخلط شرائح البطاطس بنصف الزيت واشوها ٣٠–٣٥ دقيقة مع التقليب.","شكل الديك الرومي والبهارات قرصاً واطهه ببقية الزيت حتى يبلغ ٧٤°م.","قدمه بين شريحتي خبز كامل مع الزبادي والطماطم والسبانخ والبطاطس بجانبه."],"tags":["Meal prep"],"allergens":["Check blend","Gluten","Milk","Wheat"],"image":"assets/recipes/38.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_39','{"id":"recipe_39","name":"Chicken shawarma rice bowl","name_ar":"بول شاورما الدجاج والأرز","category":"Main meals","minutes":30,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"chicken","name":"Chicken breast · raw, skinless","name_ar":"صدر دجاج نيئ دون الجلد","protein":23,"carbs":0,"fat":2,"fiber":0,"allergens":"","unit":"g","quantity":170},{"id":"rice","name":"Basmati rice · dry","name_ar":"أرز بسمتي جاف","protein":7.5,"carbs":78,"fat":0.7,"fiber":1.2,"allergens":"","unit":"g","quantity":60},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":80},{"id":"cucumber","name":"Cucumber · raw","name_ar":"خيار نيئ","protein":0.7,"carbs":2,"fat":0.1,"fiber":0.5,"allergens":"","unit":"g","quantity":100},{"id":"tomato","name":"Tomatoes · raw","name_ar":"طماطم نيئة","protein":0.9,"carbs":2.7,"fat":0.2,"fiber":1.2,"allergens":"","unit":"g","quantity":100},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":6},{"id":"lemon","name":"Lemon juice","name_ar":"عصير ليمون","protein":0.4,"carbs":2.5,"fat":0.2,"fiber":0.3,"allergens":"","unit":"g","quantity":15},{"id":"garlic","name":"Garlic · raw","name_ar":"ثوم نيئ","protein":6,"carbs":28,"fat":0.5,"fiber":2,"allergens":"","unit":"g","quantity":5},{"id":"spice","name":"Ground spice mix · unsalted","name_ar":"بهارات مطحونة دون ملح","protein":10,"carbs":35,"fat":10,"fiber":20,"allergens":"Check blend","unit":"g","quantity":3}],"steps":["Coat thin chicken strips in half the yogurt, spices, garlic and oil. Start cooking the rice.","Pan-cook chicken until browned and its centre reaches 74°C. Mix remaining yogurt with lemon for the sauce.","Serve chicken over rice with chopped cucumber, tomato and the yogurt sauce."],"steps_ar":["غط شرائح الدجاج بنصف الزبادي والبهارات والثوم والزيت وابدأ طهي الأرز.","اطه الدجاج حتى يحمر وتبلغ حرارته الداخلية ٧٤°م واخلط بقية الزبادي بالليمون للصلصة.","قدم الدجاج فوق الأرز مع الخيار والطماطم المقطعة وصلصة الزبادي."],"tags":["Meal prep"],"allergens":["Check blend","Milk"],"image":"assets/recipes/39.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_40','{"id":"recipe_40","name":"Date walnut overnight oats","name_ar":"شوفان ليلي بالتمر والجوز","category":"Breakfast","minutes":5,"wait_minutes":240,"servings":1,"summary":"A simple start, with clear portions and everyday ingredients.","summary_ar":"بداية بسيطة بمقادير واضحة ومكونات يومية.","ingredients":[{"id":"oats","name":"Rolled oats · dry","name_ar":"شوفان ملفوف · جاف","protein":13,"carbs":60,"fat":7,"fiber":10,"allergens":"Gluten","unit":"g","quantity":50},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":170},{"id":"milk","name":"Milk · 1.5% fat","name_ar":"حليب قليل الدسم","protein":3.5,"carbs":5,"fat":1.5,"fiber":0,"allergens":"Milk","unit":"g","quantity":80},{"id":"date","name":"Dates · pitted","name_ar":"تمر دون النوى","protein":2,"carbs":68,"fat":0.2,"fiber":7,"allergens":"","unit":"g","quantity":25},{"id":"walnut","name":"Walnuts","name_ar":"جوز","protein":15,"carbs":7,"fat":65,"fiber":6.7,"allergens":"Tree nuts","unit":"g","quantity":15},{"id":"cinnamon","name":"Cinnamon · ground","name_ar":"قرفة مطحونة","protein":4,"carbs":28,"fat":1,"fiber":53,"allergens":"","unit":"g","quantity":1}],"steps":["Pit and finely chop the dates. Stir oats, yogurt, milk, dates and cinnamon together.","Cover and refrigerate for at least 4 hours or overnight.","Stir before serving and finish with chopped walnuts."],"steps_ar":["انزع نوى التمر وافرمه واخلط الشوفان والزبادي والحليب والتمر والقرفة.","غطه وبرده ٤ ساعات على الأقل أو طوال الليل.","قلبه قبل التقديم وأضف الجوز المفروم."],"tags":["Vegetarian","No-cook"],"allergens":["Gluten","Milk","Tree nuts"],"image":"assets/recipes/40.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','welcome','{"id":"welcome","category":"Getting started","title":"Your portal, your plan","summary":"Know where to find your plans and how to keep your coach informed.","image":"assets/education/education-welcome.webp","sections":[["Your home base","Your dashboard brings together the plan assigned to you, your nutrition strategy and your next check-in. Open the reference you need, then return when you have feedback to share."],["Before you begin","Check your profile, goals, availability, food preferences and any limitations with your coach. Read the coaching guidelines and the current version of each assigned plan."],["Keep the feedback useful","A short specific note about training, meals or recovery helps your coach make the next adjustment. You do not need to enter every set during your training."],["Build your first-week routine","Start by choosing realistic places in your week for the sessions your coach has assigned. Review the whole training day before you arrive at the gym: the exercise order, the equipment you need and any substitutions already agreed. Then open Nutrition and select the day variant that applies. A recipe is a preparation guide; it becomes part of your daily plan when your coach places it there. Simply opening a recipe does not change your calorie target.\n\nKeep the portal useful and lightweight. It is a reference for preparation and reflection, so you can put your phone away when you train. A short review after a session is often enough to remember the questions you want to raise."],["Make the next action obvious","Use Dashboard for your current priorities, Training for the prescription, Recipes for cooking instructions and Check-in for feedback. The Explore menu brings every available resource together. Your package determines which areas you can open. If you cannot find an expected plan, ask your coach to confirm both the assignment and publication status.\n\nBefore your first review, check that your profile reflects your current schedule and food preferences. These details make the coaching conversation more specific than a simple “good week” or “bad week”."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"welcome","category":"Getting started","title":"Your portal, your plan","summary":"Know where to find your plans and how to keep your coach informed.","image":"assets/education/education-welcome.webp","sections":[["Your home base","Your dashboard brings together the plan assigned to you, your nutrition strategy and your next check-in. Open the reference you need, then return when you have feedback to share."],["Before you begin","Check your profile, goals, availability, food preferences and any limitations with your coach. Read the coaching guidelines and the current version of each assigned plan."],["Keep the feedback useful","A short specific note about training, meals or recovery helps your coach make the next adjustment. You do not need to enter every set during your training."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','plans','{"id":"plans","category":"Training","title":"Read your training plan","summary":"Understand the difference between a prescription and feedback.","image":"assets/education/education-plans.webp","sections":[["Read the full day","Review the exercise order, sets, repetition range, written rest guidance and coach notes. Any sample working load is a plan example, not a required starting weight."],["Exercise references","Open the linked exercise to see its muscle targets, equipment and catalogue cue. Each photograph illustrates its linked exercise. Read the written cue and ask your coach to confirm your setup."],["Changes and questions","Tell your coach about unavailable equipment, discomfort or a schedule change. The coach can publish a new plan version while your earlier check-ins remain in the history."],["Understand effort, repetitions and rest","A prescription such as 3 × 8–12 means three working sets, with each set aiming for the stated repetition range. Warm-up sets are separate unless your coach says otherwise. The working load should allow the intended technique and range of motion. Completing a number by shortening the movement or losing control does not make the set equivalent.\n\nRest is part of the prescription. It allows the next set to be performed with the required quality. If a busy gym interrupts the order or changes your rest substantially, keep a short note rather than treating the session as identical to the previous week."],["Progress without guessing","Agree with your coach how progression will be judged. One example is to build repetitions within a range before increasing load, while keeping technique, exercise setup and rest comparable. This is an example of a progression method, not an automatic rule that overrides your programme.\n\nUseful feedback identifies the exercise, what you completed and what limited you. “Last two repetitions became rushed” gives your coach more to work with than “too hard”. Report pain, unusual symptoms or a movement you cannot control, and stop the affected exercise rather than forcing a target."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"plans","category":"Training","title":"Read your training plan","summary":"Understand the difference between a prescription and feedback.","image":"assets/education/education-plans.webp","sections":[["Read the full day","Review the exercise order, sets, repetition range, written rest guidance and coach notes. Any sample working load is a plan example, not a required starting weight."],["Exercise references","Open the linked exercise to see its muscle targets, equipment and catalogue cue. Each photograph illustrates its linked exercise. Read the written cue and ask your coach to confirm your setup."],["Changes and questions","Tell your coach about unavailable equipment, discomfort or a schedule change. The coach can publish a new plan version while your earlier check-ins remain in the history."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','nutrition','{"id":"nutrition","category":"Nutrition","title":"Make your meal plan practical","summary":"Portions, reference units and preparation all matter.","image":"assets/education/education-nutrition.webp","sections":[["Understand the reference","Some foods are listed per 100 grams, others per egg, packet or tablespoon. The quantity in your meal uses the same unit. Rice labelled uncooked is weighed before cooking."],["Plan total versus target","The planned meal total is calculated from the ingredients. The coach target is shown separately. A difference is visible so the plan can be adjusted rather than hidden."],["Bring practical feedback","Tell your coach which meals suit your routine, which ingredients are unavailable and what you would like to swap. Check allergies and preferences before following a new plan."],["Read a meal from ingredients upward","The ingredient amount and preparation state are the starting point. A cooked weight includes absorbed or lost water; a raw or dry weight does not represent the same portion after cooking. Oils, nut butters, sauces and toppings also contribute nutrients. Use the measured amounts in the plan instead of copying the visual size of the photograph.\n\nThe recipe panel shows estimated calories, protein, carbohydrate, fat and fibre for the displayed number of servings. If a recipe makes four servings, the ingredient editor describes the whole batch and the client view scales it to the assigned portion. Brand differences and cooking losses mean these are planning estimates."],["Make consistency practical","Choose a shopping and preparation routine you can repeat. Prepare a few ingredients in advance, keep convenient options available and tell your coach when a meal repeatedly conflicts with work or family commitments. The most elaborate meal is not automatically the most useful one.\n\nBefore a new assignment, check the ingredient list and allergen notes against the actual product label and your personal requirements. Your coach can change the recipe, portion or meal timing. Do not add an extra assigned recipe on top of the full plan unless that is what has been agreed."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"nutrition","category":"Nutrition","title":"Make your meal plan practical","summary":"Portions, reference units and preparation all matter.","image":"assets/education/education-nutrition.webp","sections":[["Understand the reference","Some foods are listed per 100 grams, others per egg, packet or tablespoon. The quantity in your meal uses the same unit. Rice labelled uncooked is weighed before cooking."],["Plan total versus target","The planned meal total is calculated from the ingredients. The coach target is shown separately. A difference is visible so the plan can be adjusted rather than hidden."],["Bring practical feedback","Tell your coach which meals suit your routine, which ingredients are unavailable and what you would like to swap. Check allergies and preferences before following a new plan."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','swaps','{"id":"swaps","category":"Nutrition","title":"Food swaps with context","summary":"Matching one nutrient does not make two foods identical.","image":"assets/education/education-swaps.webp","sections":[["Use a confirmed swap","The swap guide matches a chosen nutrient using the reference portions. Protein-equivalent servings can have different calories, fats and food volumes."],["Keep preparation consistent","Use the preparation state and portion unit written in the plan. A dry rice serving and a cooked rice serving cannot be exchanged gram for gram."],["Ask for an alternative","Report availability, preferences or digestion issues in your check-in. Your coach decides whether to change the food, portion or full meal."],["Compare the whole meal","A protein-based swap answers one specific question: what portion provides a similar amount of protein? It does not guarantee equal energy, carbohydrate, fat, fibre, sodium or fullness. For example, changing between a lean protein and a fattier protein may require a separate adjustment to the oil or other ingredients in the meal.\n\nLook at the resulting meal totals and the daily plan rather than one green number. Recipe assignments preserve the version chosen by your coach, so a newly edited template does not silently change a previously assigned portion."],["Describe the replacement you need","A helpful request includes the original ingredient, the reason for changing it and what is realistically available. Mention whether the issue is taste, cost, cooking time, availability or tolerance. Give the coach a product label or clear ingredient description if the replacement is packaged.\n\nOnce the alternative is agreed, use the preparation state and portion that belong to that alternative. A similar-looking plate is not a reliable measurement. Keep one consistent method so the next check-in reflects what you actually followed."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"swaps","category":"Nutrition","title":"Food swaps with context","summary":"Matching one nutrient does not make two foods identical.","image":"assets/education/education-swaps.webp","sections":[["Use a confirmed swap","The swap guide matches a chosen nutrient using the reference portions. Protein-equivalent servings can have different calories, fats and food volumes."],["Keep preparation consistent","Use the preparation state and portion unit written in the plan. A dry rice serving and a cooked rice serving cannot be exchanged gram for gram."],["Ask for an alternative","Report availability, preferences or digestion issues in your check-in. Your coach decides whether to change the food, portion or full meal."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','checkin','{"id":"checkin","category":"Coaching","title":"A useful weekly check-in","summary":"Give your coach the context behind the numbers.","image":"assets/education/education-checkin.webp","sections":[["Review the week","Consider training frequency, nutrition adherence, energy, sleep, hunger and digestion. An honest incomplete week is more useful than an invented perfect week."],["Describe one example","Say what made a meal difficult or why a training day moved. Include changes to schedule, travel or equipment where relevant."],["Submit and review","Save a draft if you need more time. Once submitted, your coach can review the entry and leave feedback alongside your original answers."],["Separate observations from interpretation","Start with facts you can describe: sessions completed, meals that were difficult to prepare, nights with less sleep and any changes in routine. Then describe how the week felt. A scale increase is an observation; “the plan has stopped working” is an interpretation that needs more context.\n\nUse the same rating scale each week. A recovery score should mean roughly the same thing to you across reviews. If you change how you interpret a rating, explain it in the notes. Consistent reporting makes patterns easier for you and your coach to discuss."],["Write feedback your coach can act on","Use a simple structure: what happened, why it mattered and what you need next. For example: “I completed three of four sessions. Thursday moved because of work, and I could not fit both lower-body days. Can we review next week’s schedule?”\n\nRead the coach response before changing several things at once. Agree on the next adjustment and keep the rest of the routine reasonably stable. A check-in is a conversation about the next useful step, not a judgement of your character or commitment."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"checkin","category":"Coaching","title":"A useful weekly check-in","summary":"Give your coach the context behind the numbers.","image":"assets/education/education-checkin.webp","sections":[["Review the week","Consider training frequency, nutrition adherence, energy, sleep, hunger and digestion. An honest incomplete week is more useful than an invented perfect week."],["Describe one example","Say what made a meal difficult or why a training day moved. Include changes to schedule, travel or equipment where relevant."],["Submit and review","Save a draft if you need more time. Once submitted, your coach can review the entry and leave feedback alongside your original answers."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','measure','{"id":"measure","category":"Progress","title":"Measure consistently","summary":"Make comparisons meaningful by keeping the method stable.","image":"assets/education/education-measure.webp","sections":[["Record the context","Use the same unit and note the date. Where possible, keep the measurement conditions consistent and tell your coach when a method changes."],["Missing is not zero","Leave an unknown measurement blank. The portal keeps missing values separate from real readings and plots only values that were entered."],["Photographs","Use comparable pose, distance, lighting and clothing for private progress references. In this frontend demo, uploaded images remain in this browser’s local data."],["Understand what a trend can tell you","A measurement is a snapshot, and its meaning depends on the method. Body weight can vary with hydration, food in the digestive system and the timing of the measurement. A tape measure can change with placement and tension. Keep these conditions as similar as reasonably possible before comparing results.\n\nUse the chart to review the direction over comparable dates rather than reacting to one point. A missing entry remains missing; it is not evidence that your weight or circumference reached zero. If the method changed, record a note so your coach can interpret the series."],["Make photographs comparable","Choose a repeatable camera position, distance, light and pose. Keep your full outline inside the frame, avoid a wide-angle close-up and use similar clothing. Front, side and back views are more useful when taken with the same setup on each date.\n\nPictures are optional coaching context, not a requirement to look a particular way on every day. Review visual changes alongside measurements, performance and how the routine feels. If you replace or remove a photo, export the data you want to keep first."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"measure","category":"Progress","title":"Measure consistently","summary":"Make comparisons meaningful by keeping the method stable.","image":"assets/education/education-measure.webp","sections":[["Record the context","Use the same unit and note the date. Where possible, keep the measurement conditions consistent and tell your coach when a method changes."],["Missing is not zero","Leave an unknown measurement blank. The portal keeps missing values separate from real readings and plots only values that were entered."],["Photographs","Use comparable pose, distance, lighting and clothing for private progress references. Uploaded photographs are saved privately in your coaching account."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','recovery','{"id":"recovery","category":"Recovery","title":"Recovery belongs in the conversation","summary":"Describe life outside the training plan.","image":"assets/education/education-recovery.webp","sections":[["Energy and sleep","Your check-in includes both hours of sleep and a quality rating. They describe different parts of the week and help provide context."],["Changing routines","Travel, work patterns and unusual fatigue can affect how manageable a plan feels. Share those changes rather than silently changing every target."],["Plan with your coach","Training and rest days are part of the assigned programme. Any change to frequency or intensity should be discussed through the coaching review."],["Look beyond a single tired day","One difficult session does not explain the whole programme. Look at the combination of sleep, work stress, soreness, appetite and repeated changes in performance. A week of unusual travel or long shifts is different from several weeks of growing fatigue under otherwise stable conditions.\n\nTell your coach which tasks feel affected and when the change began. “My usual warm-up felt unusually difficult on both lower-body days” gives clearer context than “recovery was bad”. Do not use wearable scores or a single rating as an automatic instruction to change the plan."],["Create a repeatable wind-down","Choose practical habits that fit your life: a more consistent bedtime, a manageable evening routine and a plan for late work or travel. The goal is a routine you can follow, not a perfect checklist that creates extra stress. Keep your agreed sleep and rest targets visible in the portal.\n\nDiscuss persistent fatigue, recurring discomfort or a meaningful drop in your capacity rather than repeatedly pushing through. Your coach can review training load and scheduling; symptoms that need medical assessment belong with a qualified healthcare professional."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"recovery","category":"Recovery","title":"Recovery belongs in the conversation","summary":"Describe life outside the training plan.","image":"assets/education/education-recovery.webp","sections":[["Energy and sleep","Your check-in includes both hours of sleep and a quality rating. They describe different parts of the week and help provide context."],["Changing routines","Travel, work patterns and unusual fatigue can affect how manageable a plan feels. Share those changes rather than silently changing every target."],["Plan with your coach","Training and rest days are part of the assigned programme. Any change to frequency or intensity should be discussed through the coaching review."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','shopping','{"id":"shopping","category":"Nutrition","title":"Prepare a useful shopping list","summary":"Turn your assigned meals into quantities you can check.","image":"assets/education/education-shopping.webp","sections":[["Choose a day variant","The grocery list uses the selected training, rest or higher-carb day. Repeating it across a week is a planning aid, not an automatic mixed-week menu."],["Check what you already have","Combined quantities keep each food’s reference unit. Review package sizes, fresh food storage and your schedule before buying."],["Simple preparation","Group meals with shared ingredients and note which quantities are raw or cooked. Keep oils, dressings and add-ons consistent with your plan."],["Build the list from your actual week","Select the day variant you plan to follow and check the number of times you will repeat it. If you use different variants, combine them deliberately instead of multiplying one training day by seven. The portal list groups the ingredients in the selected day; it does not assume a whole week of identical meals.\n\nCompare required quantities with what is already in the cupboard, then convert them into realistic package sizes. Check whether an amount is dry, cooked, drained or counted before shopping. Repeated ingredients from individually created recipe plans may need to be combined by name and preparation state."],["Prepare components, then assemble","Group practical tasks: wash vegetables, portion dry ingredients and plan which foods will be cooked fresh. Keep sauces and oils measured separately where the recipe requires them. Label prepared portions so a larger container does not become an uncertain serving size.\n\nFollow product storage directions and cool and refrigerate prepared food promptly. Cooking times in recipes are guides; use doneness checks and a food thermometer where specified. If your schedule changes, ask for a simpler recipe rather than preparing a complicated plan you cannot maintain."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"shopping","category":"Nutrition","title":"Prepare a useful shopping list","summary":"Turn your assigned meals into quantities you can check.","image":"assets/education/education-shopping.webp","sections":[["Choose a day variant","The grocery list uses the selected training, rest or higher-carb day. Repeating it across a week is a planning aid, not an automatic mixed-week menu."],["Check what you already have","Combined quantities keep each food’s reference unit. Review package sizes, fresh food storage and your schedule before buying."],["Simple preparation","Group meals with shared ingredients and note which quantities are raw or cooked. Keep oils, dressings and add-ons consistent with your plan."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','travel','{"id":"travel","category":"Lifestyle","title":"Eating out and travel","summary":"Take your plan into the real world.","image":"assets/education/education-travel.webp","sections":[["Plan ahead","Discuss regular restaurant meals, travel and food availability with your coach. Agree on flexible meal choices rather than guessing exact macros for every unfamiliar dish."],["Keep a short note","Describe the meal and the context in your nutrition feedback. Use an estimate only if your coach has asked for one."],["Return to your routine","A changed meal is useful information for the next adjustment. Review what was manageable and prepare the next planned meal."],["Use a flexible decision sequence","Begin with the choices you can see: an appropriate protein option, a carbohydrate portion, vegetables or fruit, and sauces or oils that are easy to identify. This helps you describe the meal and discuss adjustments without pretending to know an exact restaurant recipe. The sequence is a planning aid, not a universal serving prescription.\n\nWhen possible, review a menu before the event and decide what would fit the approach agreed with your coach. Ask about preparation and ingredients if allergies or dietary requirements matter. A menu photograph cannot confirm hidden ingredients."],["Return without compensation","After a changed meal, return to the next agreed meal and routine. Avoid inventing a punishment workout or an unplanned fast to compensate. Your feedback can be brief: what changed, how hungry or satisfied you felt and whether the same situation will happen again.\n\nFor longer travel, discuss the equipment, food access, time zone and number of realistic training opportunities in advance. A deliberate temporary plan gives the coach better information than several improvised changes made without context."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"travel","category":"Lifestyle","title":"Eating out and travel","summary":"Take your plan into the real world.","image":"assets/education/education-travel.webp","sections":[["Plan ahead","Discuss regular restaurant meals, travel and food availability with your coach. Agree on flexible meal choices rather than guessing exact macros for every unfamiliar dish."],["Keep a short note","Describe the meal and the context in your nutrition feedback. Use an estimate only if your coach has asked for one."],["Return to your routine","A changed meal is useful information for the next adjustment. Review what was manageable and prepare the next planned meal."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','guidelines','{"id":"guidelines","category":"Coaching","title":"Coaching guidelines","summary":"A clear working agreement for both sides.","image":"assets/education/education-guidelines.webp","sections":[["Your part","Keep profile information current, read your assigned plans, submit the agreed check-in and raise questions or problems promptly."],["Your coach’s part","Your coach sets targets, reviews feedback, approves exercise and food references, and publishes changes to your assigned plans."],["Support","Use the contact details your coach provides. This portal does not contain chat, payments, live training monitoring or video calls."],["Know what changes a plan","The coach publishes your training and nutrition assignments. Your check-in provides the context for the next decision, but it does not automatically change exercises or calorie targets. Read the current plan version after an update and ask which parts changed if that is unclear.\n\nRecipe templates, client recipe assignments and published meal plans are separate. Editing a template preserves the version already assigned to you until the coach reassigns it. Adding a recipe to your meal plan creates an individual plan copy, so another client’s meals are not changed by your adjustment."],["Keep the working relationship clear","Agree on the check-in day, the channel for questions and the usual response window directly with your coach. Use concise, specific messages and distinguish routine feedback from something that needs timely attention. The portal stores your coaching records; it is not an emergency response service.\n\nKeep account details private and review what information you include in photographs and written notes. Before changing device or replacing a local copy, save a backup. Where an online account is connected, check that the save completed before closing the page."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"guidelines","category":"Coaching","title":"Coaching guidelines","summary":"A clear working agreement for both sides.","image":"assets/education/education-guidelines.webp","sections":[["Your part","Keep profile information current, read your assigned plans, submit the agreed check-in and raise questions or problems promptly."],["Your coach’s part","Your coach sets targets, reviews feedback, approves exercise and food references, and publishes changes to your assigned plans."],["Support","Use the contact details your coach provides. This portal does not contain chat, payments, live training monitoring or video calls."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','strength-foundation','{"id":"strength-foundation","title":"Inside the Strength Foundation programme","title_ar":"داخل برنامج تأسيس القوة","summary":"Understand the push, pull, legs and upper-body structure already available in your portal.","summary_ar":"افهم تقسيم الدفع والسحب والساقين والجزء العلوي المتاح في بوابتك.","category":"Training knowledge","image":"","symbol":"workouts","related_program_id":"plan_strength","sections":[["The purpose of a split","A split organises training across the week. The Strength Foundation template separates pushing, pulling and lower-body work, then adds a balanced upper-body session. The labels describe where attention goes on each day; they are not a guarantee of a result. The useful programme is the one whose exercise choices, workload and schedule match the person using it.\n\nBodybuilding has long used split routines to distribute work across sessions. In this portal, the template gives the coach an editable starting structure rather than a rigid system every client must follow."],["How the template is organised","The default template contains Push on Monday, Pull on Tuesday, Legs on Thursday and Upper on Saturday. Push focuses on chest, shoulders and triceps; Pull on back and biceps; Legs on the lower body; Upper returns to chest, back and shoulders. Always check your assigned version because your coach can change these days and exercises.\n\nThe additional upper-body day changes the distribution of weekly work. Do not assume every muscle receives the same number of sets just because the plan has four sessions."],["What the structure can help with","A focused session makes preparation simpler: you can review a smaller group of movements and the equipment they require. Spreading work across the week can also make each session easier to schedule than placing everything into one day. These are organisational benefits, not evidence that one split is always superior.\n\nThe four-day commitment is also a constraint. If you repeatedly miss the same day, the programme you actually complete differs from the template. Tell your coach before trying to squeeze several sessions into a single catch-up workout."],["How to evaluate a useful week","Review whether you completed the agreed sessions, whether the prescribed movements remained controlled and whether the workload fitted your recovery. A good week does not require a personal best on every exercise. Clear technique, a repeatable setup and honest feedback make later comparisons more useful.\n\nTrack progression according to the method agreed with your coach. Avoid increasing load, sets and frequency simultaneously without a clear reason; it becomes harder to know what caused the change in how the plan feels."],["Use the guide with your assigned plan","Open Training to see your personal prescription, then use the exercise library for setup and technique cues. The template described here may have been adapted for your equipment, availability or limitations. If the coach has assigned a different programme, this guide is background knowledge and does not replace it.\n\nBring one specific question to your next check-in: which exercise, scheduling issue or recovery pattern would make the next week more manageable?"]],"sections_ar":[["هدف التقسيم","ينظم التقسيم التدريب خلال الأسبوع. يفصل قالب تأسيس القوة الدفع والسحب والجزء السفلي، ثم يضيف جلسة علوية متوازنة. تصف التسميات تركيز اليوم ولا تضمن نتيجة. يفيد البرنامج عندما تتناسب تمارينه وحمله وجدوله مع الشخص.\n\nتستخدم تدريبات بناء الأجسام التقسيم لتوزيع العمل. هنا يمنح القالب المدرب بداية قابلة للتعديل وليست نظاماً إلزامياً للجميع."],["تنظيم القالب","يحتوي القالب الافتراضي على الدفع يوم الاثنين والسحب الثلاثاء والساقين الخميس والجزء العلوي السبت. يركز الدفع على الصدر والأكتاف والترايسبس، والسحب على الظهر والبايسبس، والساقان على الجزء السفلي، والعلوي على الصدر والظهر والأكتاف. راجع نسختك المخصصة لأن المدرب يستطيع تغيير الأيام والتمارين.\n\nتغير الجلسة العلوية الإضافية توزيع العمل. لا تفترض تساوي مجموعات كل العضلات لمجرد وجود أربع جلسات."],["فوائد التنظيم","تسهل الجلسة المركزة التحضير بمراجعة مجموعة أصغر من الحركات والمعدات. وقد يسهل توزيع العمل جدولة الجلسات بدلاً من جمعها في يوم واحد. هذه فوائد تنظيمية وليست دليلاً على تفوق تقسيم واحد دائماً.\n\nالالتزام بأربعة أيام قيد أيضاً. تكرار تفويت يوم يغير البرنامج المنجز فعلياً. أخبر المدرب قبل ضغط عدة جلسات في تمرين تعويضي واحد."],["تقييم الأسبوع","راجع إكمال الجلسات والسيطرة على الحركات وتناسب الحمل مع التعافي. لا يتطلب الأسبوع الجيد رقماً شخصياً جديداً في كل تمرين. تجعل التقنية والإعداد الثابت والملاحظات الصادقة المقارنة مفيدة.\n\nتابع التقدم بالطريقة المتفق عليها. تجنب زيادة الوزن والمجموعات والتكرار الأسبوعي معاً دون سبب واضح، كي تفهم أثر التغيير."],["استخدم الدليل مع خطتك","افتح التدريب لرؤية وصفك الشخصي ومكتبة التمارين لإرشادات الإعداد. قد يعدل القالب حسب معداتك وتوفرك وحدودك. إذا خصص المدرب برنامجاً مختلفاً، فهذا الدليل معرفة عامة ولا يستبدله.\n\nقدم سؤالاً محدداً في المتابعة: أي تمرين أو مشكلة جدول أو نمط تعاف سيجعل الأسبوع التالي أسهل؟"]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','upper-lower','{"id":"upper-lower","title":"Upper / Lower: organise four purposeful sessions","title_ar":"العلوي والسفلي: تنظيم أربع جلسات هادفة","summary":"A practical guide to the four-day Upper / Lower template, its benefits and its trade-offs.","summary_ar":"دليل عملي لقالب العلوي والسفلي ذي الأربع جلسات وفوائده وحدوده.","category":"Training knowledge","image":"","symbol":"grid","related_program_id":"plan_build","sections":[["What upper / lower means","Upper / lower describes how sessions are divided by region of the body. Upper sessions usually combine pressing and pulling patterns; lower sessions organise knee-dominant and hip-dominant work with supporting exercises. It is a scheduling framework, not a special type of muscle contraction.\n\nLike other split routines, the idea is to distribute a useful amount of work across a week. The exact exercise list, effort, sets and rest periods matter more than the name on the programme."],["Read this portal’s actual template","The included template contains a balanced Upper session, a lower-body Legs session, a Push session and a Lower session with glute and hamstring focus. It is therefore an upper/lower-oriented template with a push emphasis on one upper day, not two identical upper sessions.\n\nThe default day labels are Monday for Push, Thursday for Legs, Friday for Lower and Saturday for Upper. The two lower-body days are consecutive in the starting template. The coach should review that spacing, exercise overlap and recovery before assigning it to an individual."],["Where the format can be useful","The separation makes it clear which movements belong to each session and gives the coach a straightforward way to adjust one part of the week. An upper session can be adapted to limited equipment without rebuilding every lower-body prescription. Similar movement patterns also make it easier to discuss a recurring setup problem.\n\nThis does not mean a four-day split is required for progress. Someone with fewer reliable training opportunities may need a different structure. The practical benefit disappears if the schedule is repeatedly impossible to complete."],["Balance effort across the week","A hard lower-body day can influence how the following day feels. Record relevant context and avoid assuming that different exercise names always mean completely different demands. Glute, hamstring and back work can overlap across movement patterns.\n\nAsk your coach how effort should vary between the sessions and how to handle a moved day. Reordering the week is sometimes useful, but the decision should preserve the intended balance rather than placing every demanding movement back to back."],["What to discuss at review","Compare the plan with your real availability, not an ideal calendar. Discuss session duration, equipment access, movement quality and recovery between the lower-body days. Your coach can change the days, exercise selection or programme itself while preserving your feedback history.\n\nThe right next step is a programme you can execute consistently and review meaningfully. Use the template as a shared starting point, then judge the assigned version by what it helps you do."]],"sections_ar":[["معنى العلوي والسفلي","يقسم هذا الأسلوب الجلسات حسب منطقة الجسم. تجمع الجلسات العلوية عادة الدفع والسحب، وتنظم السفلية العمل المتمحور حول الركبة والورك مع تمارين مساعدة. إنه إطار للجدولة وليس نوعاً خاصاً من الانقباض.\n\nالهدف توزيع العمل خلال الأسبوع. التمارين والجهد والمجموعات والراحة أهم من اسم البرنامج."],["اقرأ القالب الفعلي","يتضمن القالب جلسة علوية متوازنة وجلسة ساقين وجلسة دفع وجلسة سفلية تركز على الأرداف والخلفية. لذلك فهو قالب علوي وسفلي مع تركيز دفع في يوم علوي، وليس جلستين علويتين متطابقتين.\n\nالأيام الافتراضية هي الاثنين للدفع والخميس للساقين والجمعة للسفلي والسبت للعلوي. اليومان السفليان متتاليان في القالب الأولي؛ على المدرب مراجعة التباعد والتداخل والتعافي قبل التخصيص."],["متى يفيد","يوضح الفصل الحركات الخاصة بكل جلسة ويسهل تعديل جزء من الأسبوع. يمكن تكييف الجلسة العلوية للمعدات المتاحة دون إعادة بناء وصف الجزء السفلي. كما يسهل مناقشة مشكلة إعداد متكررة.\n\nلا يعني ذلك أن التقسيم لأربعة أيام شرط للتقدم. قد يحتاج من يتوفر له وقت أقل إلى تنظيم مختلف. تختفي الفائدة العملية إذا تعذر إكمال الجدول باستمرار."],["وازن الجهد","قد تؤثر جلسة سفلية شديدة على اليوم التالي. سجل السياق ولا تفترض أن اختلاف أسماء التمارين يعني اختلافاً كاملاً في المتطلبات؛ قد تتداخل عضلات الأرداف والخلفية والظهر.\n\nاسأل المدرب كيف يتوزع الجهد وكيف تتعامل مع نقل يوم. قد تفيد إعادة الترتيب بشرط الحفاظ على التوازن المقصود."],["ماذا تناقش","قارن الخطة بوقتك الحقيقي لا بجدول مثالي. ناقش مدة الجلسة والمعدات وجودة الحركة والتعافي بين اليومين السفليين. يستطيع المدرب تغيير الأيام أو التمارين أو البرنامج مع الحفاظ على تاريخ الملاحظات.\n\nالخطوة المناسبة برنامج تستطيع تنفيذه ومراجعته باستمرار. استخدم القالب نقطة بداية مشتركة وقيم النسخة المخصصة بما تساعدك على إنجازه."]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','hit-hiit','{"id":"hit-hiit","title":"HIT and HIIT: two different ideas","title_ar":"HIT وHIIT: فكرتان مختلفتان","summary":"Understand high-effort strength training, interval conditioning and why the distinction matters.","summary_ar":"افهم تدريب القوة عالي الجهد واللياقة المتقطعة وأهمية التمييز بينهما.","category":"Training knowledge","image":"","symbol":"energy","related_program_id":"","sections":[["Start with the terms","HIT commonly means High Intensity Training in a strength-training context: a low-volume approach that places strong emphasis on effort during a small number of working sets. HIIT means High Intensity Interval Training: harder conditioning intervals alternated with recovery periods. The words look similar, but they describe different programming ideas.\n\nA difficult set of a resistance exercise is not automatically a HIIT workout. A timed circuit is not automatically the same as a low-volume strength programme. Ask what the session is intended to develop before copying its label."],["A short historical perspective","High-effort, low-volume strength training is associated with the Nautilus tradition and Arthur Jones. Its emphasis on brief, demanding work helped shape a continuing discussion about how much training is needed. Historical influence should not be confused with proof that a single method is best for everyone.\n\nA widely cited 1996 study by Izumi Tabata and colleagues examined very demanding intermittent cycle training and changes in aerobic and anaerobic capacity. It studied a specific protocol under controlled conditions. A general online “Tabata” circuit is not automatically equivalent to that experiment."],["Effort and volume are different variables","Effort describes how demanding a set is relative to what you can perform. Volume describes how much work is prescribed, commonly discussed through working sets and repetitions. Increasing effort does not make the amount of work irrelevant.\n\nIn one eight-week resistance-training trial in trained men, groups using different numbers of sets improved strength, while higher-volume conditions produced greater growth at several measured muscle sites. That finding does not prescribe your programme, but it is a useful reason to avoid the claim that the fewest possible sets always maximise muscle growth."],["Where intervals fit","Intervals organise conditioning into periods of work and recovery. The modality, effort, work duration, recovery duration and total repetitions all change the demand. Ten seconds of work on a bike and a minute of repeated jumps are not interchangeable because both are called intense.\n\nPossible benefits include a clearly structured session and a way to target conditioning within a limited time. The trade-off is that demanding intervals still require recovery and may affect the rest of your training week. More exhaustion is not the same as a better programme."],["Use the distinction in your coaching","The portal’s Strength Foundation and Upper / Lower templates are resistance-training structures; neither becomes a HIT or HIIT protocol simply by shortening rest. The Core & Activity Reference is also not labelled here as a validated interval protocol.\n\nIf you are interested in either approach, ask your coach how it would fit your goals, current ability, technique and recovery. Confirm the exact prescription instead of adding all-out intervals or failure sets on top of the existing plan. Stop an exercise you cannot control, and raise pain or unusual symptoms promptly."]],"sections_ar":[["ابدأ بالمصطلحات","يشير HIT في سياق القوة غالباً إلى أسلوب قليل الحجم يركز على جهد مرتفع في عدد صغير من مجموعات العمل. أما HIIT فهو فترات لياقة أشد تتناوب مع الراحة. تتشابه الكلمات لكن الفكرة مختلفة.\n\nالمجموعة الصعبة في المقاومة ليست تلقائياً HIIT، والدائرة المؤقتة ليست بالضرورة برنامج قوة قليل الحجم. اسأل عن هدف الجلسة قبل تقليد الاسم."],["لمحة تاريخية","يرتبط تدريب القوة عالي الجهد وقليل الحجم بتقليد نوتيلوس وآرثر جونز. ساهم التركيز على العمل القصير والشديد في النقاش حول مقدار التدريب المطلوب. التأثير التاريخي لا يثبت أن طريقة واحدة أفضل للجميع.\n\nدرست تجربة مشهورة لإيزومي تاباتا وزملائه عام ١٩٩٦ تدريب دراجات متقطعاً شديداً والتغيرات في القدرة الهوائية واللاهوائية. اختبرت بروتوكولاً محدداً تحت ظروف مضبوطة، ولا تعادله تلقائياً أي دائرة تاباتا على الإنترنت."],["الجهد والحجم مختلفان","يصف الجهد صعوبة المجموعة مقارنة بقدرتك، ويصف الحجم كمية العمل مثل مجموعات العمل والتكرارات. زيادة الجهد لا تلغي أهمية كمية العمل.\n\nفي تجربة مقاومة امتدت ثمانية أسابيع على رجال مدربين، تحسنت القوة مع أحجام مختلفة، بينما حققت بعض القياسات نمواً أكبر مع الحجم الأعلى. لا تحدد النتيجة برنامجك، لكنها سبب لتجنب ادعاء أن أقل عدد من المجموعات يعظم النمو دائماً."],["مكان الفترات","تنظم الفترات اللياقة إلى عمل وتعاف. تغير الأداة والجهد ومدة العمل والراحة وعدد التكرارات المتطلبات. عشر ثوان على الدراجة ودقيقة قفز متكرر ليستا بديلين لمجرد وصفهما بالشدة.\n\nمن الفوائد جلسة واضحة وتنظيم اللياقة ضمن وقت محدود. لكن الفترات الشديدة تحتاج تعافياً وقد تؤثر في الأسبوع التدريبي. الإرهاق الأكبر لا يعني برنامجاً أفضل."],["استخدم التمييز","قالبا تأسيس القوة والعلوي والسفلي في البوابة تنظيمان للمقاومة؛ تقصير الراحة لا يحولهما تلقائياً إلى HIT أو HIIT. كما لا يصنف مرجع الجذع والنشاط هنا كبروتوكول فترات مثبت.\n\nإذا رغبت في أحد الأسلوبين، ناقش ملاءمته لأهدافك وقدرتك وتقنيتك وتعافيك. حدد الوصف بدقة بدلاً من إضافة فترات قصوى أو مجموعات فشل فوق الخطة. أوقف التمرين غير المسيطر عليه وأبلغ عن الألم أو الأعراض غير المعتادة."]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
